import json, sys, os, numpy as np
from scipy import stats
from statsmodels.tsa.stattools import adfuller
from statsmodels.tsa.vector_ar.var_model import VAR

N_PERM = 5000; ALPHA_SIG = 0.05
CANARIES = ["token_entropy", "ece"]; DOWNSTREAMS = ["distinct_3"]
HIGHER_IS_WORSE = {"ece"}
LOWER_IS_WORSE = {"token_entropy", "distinct_1", "distinct_2", "distinct_3", "mauve"}

RESULTS_DIR = sys.argv[1]
END_GEN = int(sys.argv[2])
ALPHA_VAL = float(sys.argv[3])
SEED_VAL = int(sys.argv[4])
OUT_PATH = sys.argv[5]

def orient(series, name):
    return -series.copy() if name in LOWER_IS_WORSE else series.copy()

def _build_lag_matrix(y, x, max_lag):
    T = len(y); n = T - max_lag; Y = y[max_lag:]
    cols_r = [np.ones(n)]
    for lag in range(1, max_lag + 1): cols_r.append(y[max_lag - lag: T - lag])
    cols_u = list(cols_r)
    for lag in range(1, max_lag + 1): cols_u.append(x[max_lag - lag: T - lag])
    return Y, np.column_stack(cols_r), np.column_stack(cols_u)

def _granger_f_stat(y, x, max_lag):
    Y, X_r, X_u = _build_lag_matrix(y, x, max_lag)
    n = len(Y); q = max_lag
    try:
        beta_r = np.linalg.lstsq(X_r, Y, rcond=None)[0]
        beta_u = np.linalg.lstsq(X_u, Y, rcond=None)[0]
    except: return np.nan
    rss_r = np.sum((Y - X_r @ beta_r)**2); rss_u = np.sum((Y - X_u @ beta_u)**2)
    df_resid = n - X_u.shape[1]
    if df_resid <= 0 or rss_u < 1e-15: return np.nan
    return ((rss_r - rss_u) / q) / (rss_u / df_resid)

def permutation_granger_test(x, y, max_lag=1, n_perm=1000, seed=42):
    x, y = np.diff(np.asarray(x,float)), np.diff(np.asarray(y,float))
    f_obs = _granger_f_stat(y, x, max_lag)
    if np.isnan(f_obs): return {"f_stat": None, "p_value": None, "significant": False}
    rng = np.random.default_rng(seed)
    null_f = np.array([_granger_f_stat(y, rng.permutation(x), max_lag) for _ in range(n_perm)])
    valid = null_f[~np.isnan(null_f)]
    if len(valid) == 0: return {"f_stat": round(float(f_obs),4), "p_value": None, "significant": False}
    p = (np.sum(valid >= f_obs) + 1) / (len(valid) + 1)
    return {"f_stat": round(float(f_obs),4), "p_value": round(float(p),6), "significant": bool(p < 0.05)}

def bh_fdr(p_values, alpha=0.05):
    pv = np.array(p_values, dtype=float); n = len(pv); valid = ~np.isnan(pv)
    adjusted = np.full(n, np.nan)
    if valid.sum() == 0: return adjusted.tolist(), [False]*n
    idx = np.where(valid)[0]; p_valid = pv[idx]; sorted_idx = np.argsort(p_valid)
    ranks = np.empty_like(sorted_idx); ranks[sorted_idx] = np.arange(1, len(p_valid)+1)
    m = len(p_valid); adj = p_valid * m / ranks; adj_sorted = adj[sorted_idx].copy()
    for i in range(m-2,-1,-1): adj_sorted[i] = min(adj_sorted[i], adj_sorted[i+1])
    adj_sorted = np.minimum(adj_sorted, 1.0); adj_final = np.empty(m)
    adj_final[sorted_idx] = adj_sorted
    for i, ix in enumerate(idx): adjusted[ix] = adj_final[i]
    sig = [(adjusted[i] < alpha if not np.isnan(adjusted[i]) else False) for i in range(n)]
    return adjusted.tolist(), sig

def naive_xcorr(c, d, cn, dn, max_lag=5):
    x, y = orient(c, cn), orient(d, dn); n = len(x)
    best_lag, best_r, best_p = 0, 0.0, 1.0
    for lag in range(-max_lag, max_lag+1):
        a, b = (x[lag:], y[:n-lag]) if lag >= 0 else (x[:n+lag], y[-lag:])
        if len(a) < 4: continue
        r, p = stats.pearsonr(a, b)
        if abs(r) > abs(best_r): best_lag, best_r, best_p = lag, r, p
    return {"method":"naive_xcorr","peak_lag":int(best_lag),"r":round(float(best_r),4),"p_value":round(float(best_p),6),"significant":bool(best_p<ALPHA_SIG)}

def diff_xcorr(c, d, cn, dn, max_lag=5):
    dx, dy = np.diff(orient(c, cn)), np.diff(orient(d, dn)); n = len(dx)
    best_lag, best_r, best_p = 0, 0.0, 1.0
    for lag in range(-max_lag, max_lag+1):
        a, b = (dx[lag:], dy[:n-lag]) if lag >= 0 else (dx[:n+lag], dy[-lag:])
        if len(a) < 4: continue
        if np.std(a) < 1e-12 or np.std(b) < 1e-12: continue
        r, p = stats.pearsonr(a, b)
        if abs(r) > abs(best_r): best_lag, best_r, best_p = lag, r, p
    return {"method":"diff_xcorr","peak_lag":int(best_lag),"r":round(float(best_r),4),"p_value":round(float(best_p),6),"significant":bool(best_p<ALPHA_SIG)}

def threshold_onset(c, d, cn, dn):
    def _onset(series, name):
        s = orient(series, name); base, sigma = s[0], np.std(s)
        if sigma < 1e-12: return None
        thresh = base + 3.0 * sigma
        for i in range(1, len(s)):
            if s[i] > thresh: return i
        return None
    c_on, d_on = _onset(c, cn), _onset(d, dn)
    lead = d_on - c_on if c_on is not None and d_on is not None else None
    return {"method":"threshold_onset","canary_onset":c_on,"downstream_onset":d_on,"lead_time":lead,"significant":bool(lead is not None and lead > 0),"threshold":"true_3sigma_d105"}

def perm_granger(c, d, cn, dn, seed):
    r = permutation_granger_test(orient(c,cn), orient(d,dn), max_lag=1, n_perm=N_PERM, seed=seed)
    return {"method":"perm_granger","f_stat":r["f_stat"],"p_value":r["p_value"],"significant":bool(r["p_value"]<0.05) if r["p_value"] is not None else False}

def ty_granger(c, d, cn, dn, max_order=2):
    x, y = orient(c,cn), orient(d,dn); n = len(x); d_max = 0
    for s in [x, y]:
        try:
            if adfuller(s, maxlag=min(3,n//3-1))[1] > 0.05: d_max = max(d_max, 1)
        except: d_max = max(d_max, 1)
    best_k, best_aic = 1, np.inf; data = np.column_stack([x, y])
    for k in range(1, max_order+1):
        try:
            r = VAR(data).fit(k)
            if r.aic < best_aic: best_k, best_aic = k, r.aic
        except: continue
    total = best_k + d_max
    if total >= n//2: total = max(1, n//2 - 1)
    try:
        r = VAR(data).fit(total); t = r.test_causality(causing=1, caused=0, kind="f")
        return {"method":"ty_granger","f_stat":round(float(t.test_statistic),4),"p_value":round(float(t.pvalue),4),"significant":bool(t.pvalue<ALPHA_SIG),"order":total,"d_max":d_max}
    except Exception as e:
        return {"method":"ty_granger","f_stat":None,"p_value":None,"significant":False,"error":str(e),"order":total,"d_max":d_max}

def main():
    data = []
    for g in range(END_GEN+1):
        p = os.path.join(RESULTS_DIR, f"gen_{g}", "metrics.json")
        if not os.path.exists(p): break
        with open(p) as f: data.append(json.load(f))
    data.sort(key=lambda x: x["generation"]); n_gens = len(data)
    print(f"Loaded {n_gens} generations")
    series = {k: [d.get(k) for d in data] for k in CANARIES + DOWNSTREAMS}
    pairs = [{"canary":c,"downstream":d} for c in CANARIES for d in DOWNSTREAMS]
    pair_results = []; perm_pf, perm_pr, diff_pf, diff_pr = [], [], [], []
    for pr in pairs:
        cn, dn = pr["canary"], pr["downstream"]
        c, d = np.array(series[cn]), np.array(series[dn])
        fn = naive_xcorr(c,d,cn,dn); fd = diff_xcorr(c,d,cn,dn)
        fo = threshold_onset(c,d,cn,dn); fp = perm_granger(c,d,cn,dn,42); ft = ty_granger(c,d,cn,dn)
        rn = naive_xcorr(d,c,dn,cn); rd = diff_xcorr(d,c,dn,cn)
        ro = threshold_onset(d,c,dn,cn); rp = perm_granger(d,c,dn,cn,42); rt = ty_granger(d,c,dn,cn)
        r = {"canary":cn,"downstream":dn,"n_points":len(c),
             "forward":{"naive_xcorr":fn,"diff_xcorr":fd,"threshold_onset":fo,"perm_granger":fp,"ty_granger":ft},
             "reverse":{"naive_xcorr":rn,"diff_xcorr":rd,"threshold_onset":ro,"perm_granger":rp,"ty_granger":rt}}
        perm_pf.append(fp["p_value"] if fp["p_value"] is not None else np.nan)
        perm_pr.append(rp["p_value"] if rp["p_value"] is not None else np.nan)
        diff_pf.append(fd["p_value"] if fd["p_value"] is not None else np.nan)
        diff_pr.append(rd["p_value"] if rd["p_value"] is not None else np.nan)
        pair_results.append(r)
    pa_f, ps_f = bh_fdr(perm_pf); pa_r, ps_r = bh_fdr(perm_pr)
    da_f, ds_f = bh_fdr(diff_pf); da_r, ds_r = bh_fdr(diff_pr)
    for i, r in enumerate(pair_results):
        r["forward"]["perm_granger"]["p_fdr"] = round(pa_f[i],6) if not np.isnan(pa_f[i]) else None
        r["forward"]["perm_granger"]["significant_fdr"] = ps_f[i]
        r["reverse"]["perm_granger"]["p_fdr"] = round(pa_r[i],6) if not np.isnan(pa_r[i]) else None
        r["reverse"]["perm_granger"]["significant_fdr"] = ps_r[i]
        r["forward"]["diff_xcorr"]["p_fdr"] = round(da_f[i],6) if not np.isnan(da_f[i]) else None
        r["forward"]["diff_xcorr"]["significant_fdr"] = ds_f[i]
        r["reverse"]["diff_xcorr"]["p_fdr"] = round(da_r[i],6) if not np.isnan(da_r[i]) else None
        r["reverse"]["diff_xcorr"]["significant_fdr"] = ds_r[i]

    consensus = []
    for r in pair_results:
        f = r["forward"]; votes = 0; ms = []
        if f["naive_xcorr"]["significant"] and f["naive_xcorr"]["peak_lag"] < 0: votes += 1; ms.append("naive")
        if f["diff_xcorr"].get("significant_fdr",False) and f["diff_xcorr"]["peak_lag"] < 0: votes += 1; ms.append("diff")
        if f["threshold_onset"]["significant"]: votes += 1; ms.append("threshold")
        if f["perm_granger"].get("significant_fdr",False): votes += 1; ms.append("perm")
        if f["ty_granger"]["significant"]: votes += 1; ms.append("ty")
        consensus.append({"pair":f"{r['canary']}<{r['downstream']}","votes":votes,"methods":ms})

    summary = {
        "perm_granger_fdr_forward_sig": int(sum(ps_f)),
        "perm_granger_fdr_reverse_sig": int(sum(ps_r)),
        "diff_xcorr_fdr_forward_sig": int(sum(ds_f)),
        "diff_xcorr_fdr_reverse_sig": int(sum(ds_r)),
        "threshold_forward_sig": sum(1 for r in pair_results if r["forward"]["threshold_onset"]["significant"]),
        "ty_forward_sig": sum(1 for r in pair_results if r["forward"]["ty_granger"]["significant"]),
        "naive_xcorr_forward_sig": sum(1 for r in pair_results if r["forward"]["naive_xcorr"]["significant"] and r["forward"]["naive_xcorr"]["peak_lag"]<0),
        "robust_pairs": sum(1 for c in consensus if c["votes"] >= 3),
        "total_pairs": len(consensus),
    }

    traj = {}
    for i, d in enumerate(data):
        traj[f"gen_{i}"] = {k: round(d.get(k),4) if d.get(k) is not None else None for k in ["token_entropy","ece","distinct_3","perplexity","mauve"]}

    def clean(o):
        if isinstance(o,(np.floating,np.float64)): return float(o)
        if isinstance(o,(np.integer,)): return int(o)
        if isinstance(o,np.bool_): return bool(o)
        if isinstance(o,dict): return {k:clean(v) for k,v in o.items()}
        if isinstance(o,list): return [clean(v) for v in o]
        return o

    result = clean({
        "meta": {"alpha":ALPHA_VAL,"seed":SEED_VAL,"n_gens":n_gens,"data_dir":RESULTS_DIR,
                 "methods":["naive_xcorr","diff_xcorr","threshold_onset","perm_granger","ty_granger"],
                 "n_perm":N_PERM,"canaries":CANARIES,"downstreams":DOWNSTREAMS,
                 "threshold_criterion":"true_3sigma_d105",
                 "note":"distinct_3 only (mauve dropped for 1.4B due to systematic near-zero range)"},
        "summary": summary, "consensus": consensus, "metrics_trajectory": traj
    })
    os.makedirs(os.path.dirname(OUT_PATH), exist_ok=True)
    with open(OUT_PATH, "w") as f: json.dump(result, f, indent=2)
    print(f"Saved: {OUT_PATH}")
    for c in consensus: print(f"  {c['pair']}: {c['votes']}/5 [{', '.join(c['methods'])}]")
    print(f"  robust_pairs(K>=3): {summary['robust_pairs']}/{summary['total_pairs']}")

if __name__ == "__main__": main()
